  "ch-17-java-lang-annotation": "496 PART II The Java Library • java.lang.management • java.lang.ref • java.lang.reflect Each is briefly described here. java.lang.annotation Java’s annotation facility is supported by java.lang.annotation. It defines the Annotation interface, the ElementType and RetentionPolicy enumerations, and several predefined annotations. Annotations are described in Chapter 12. java.lang.instrument java.lang.instrument defines features that can be used to add instrumentation to various aspects of program execution. It defines the Instrumentation and ClassFileTransformer interfaces, and the ClassDefinition class. java.lang.invoke java.lang.invoke supports dynamic languages. It includes classes such as CallSite, MethodHandle, and MethodType. java.lang.management The java.lang.management package provides management support for the JVM and the execution environment. Using the features in java.lang.management, you can observe and manage various aspects of program execution. java.lang.ref You learned earlier that the garbage collection facilities in Java automatically determine when no references exist to an object. The object is then assumed to be no longer needed and its memory is reclaimed. The…",
